package org.somalley

fun main() {
    val likes = readln().toInt()
    println("Понравилось $likes ${ peopleFormatted(likes) }")
}

fun peopleFormatted(count: Int): String =
    if ((count % 10 == 1) != (count % 100 == 11))
        "человеку"
    else
        "людям"
